INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4700, 'output gap', '/ˈaʊtpʊt ɡæp/', 'noun', '{"zh-TW":["產出缺口"],"en":["the difference between actual economic output and its full potential"]}', NULL, 'positive output gap / negative output gap / close the output gap', '[{"en":"A negative output gap indicates the economy is operating below capacity.","zh-TW":"負產出缺口表明經濟低於產能水平運作。"},{"en":"The central bank monitors the output gap to guide monetary policy decisions.","zh-TW":"中央銀行監測產出缺口以指導貨幣政策決策。"}]', NULL, NULL, 4, 4700, NULL),
(4701, 'outreach', '/ˈaʊtriːtʃ/', 'noun', '{"zh-TW":["外展；推廣活動"],"en":["the extension of services or influence to more people"]}', NULL, 'community outreach / outreach program', '[{"en":"The company''s outreach program supports local schools.","zh-TW":"公司的外展計劃支持當地學校。"},{"en":"Outreach efforts increased awareness of the new services.","zh-TW":"推廣工作提高了對新服務的認知度。"}]', '{"verb":"reach out"}', NULL, 3, 4701, 898),
(4702, 'outside', '/ˌaʊtˈsaɪd/', 'preposition', '{"zh-TW":["在…外面"],"en":["not inside; beyond"]}', NULL, 'outside the box / outside help', '[{"en":"We need to think outside the box.","zh-TW":"我們需要跳脫框架思考。"},{"en":"We may need outside help.","zh-TW":"我們可能需要外部幫助。"}]', '{"preposition":"outside","noun":"outsider","adjective":"outside"}', NULL, 3, 4702, NULL),
(4703, 'outsource', '/ˈaʊtsɔːrs/', 'verb', '{"zh-TW":["外包"],"en":["to hire an outside company to do work"]}', NULL, 'outsource production / outsource IT', '[{"en":"We outsource IT support to reduce costs.","zh-TW":"我們將IT支援外包以降低成本。"},{"en":"Many firms outsource manufacturing overseas.","zh-TW":"許多公司將製造外包到海外。"}]', '{"verb":"outsource","noun":"outsourcing"}', NULL, 3, 4703, 703),
(4704, 'outsource to a third party', '/ˌaʊtˈsɔːrs tə ə θɜːrd ˈpɑːrti/', 'verb', '{"zh-TW":["外包給第三方"],"en":["to delegate a business function to an external service provider"]}', NULL, 'outsource logistics to a third party / outsource IT to a third party', '[{"en":"The company outsourced payroll to a third party to save time.","zh-TW":"公司將薪資外包給第三方以節省時間。"},{"en":"Outsourcing to a third party can reduce costs but requires strong contracts.","zh-TW":"外包給第三方可以降低成本，但需要強有力的合約。"}]', NULL, NULL, 5, 4704, NULL),
(4705, 'outsourced service', '/ˌaʊtˈsɔːrst ˈsɜːrvɪs/', 'noun', '{"zh-TW":["外包服務"],"en":["a service performed by an external provider on behalf of a company"]}', NULL, 'contract an outsourced service / outsourced service provider', '[{"en":"Payroll processing was moved to an outsourced service to save costs.","zh-TW":"薪資處理被轉移到外包服務以節省成本。"},{"en":"An outsourced service provider must meet the same quality standards as internal teams.","zh-TW":"外包服務提供商必須達到與內部團隊相同的質量標準。"}]', NULL, NULL, 5, 4705, NULL),
(4706, 'outsourcing', '/ˈaʊtsɔːrsɪŋ/', 'noun', '{"zh-TW":["外包"],"en":["contracting work to an external organization"]}', NULL, 'IT outsourcing / outsourcing contract', '[{"en":"Outsourcing customer support reduced costs significantly.","zh-TW":"外包客戶支援大幅降低了成本。"},{"en":"The company is outsourcing its payroll processing.","zh-TW":"公司正在外包其薪資處理業務。"}]', '{"verb":"outsource","adjective":"outsourced"}', NULL, 4, 4706, 805),
(4707, 'outsourcing agreement', '/ˌaʊtˈsɔːrsɪŋ əˈɡriːmənt/', 'noun', '{"zh-TW":["外包協議"],"en":["a contract governing the delegation of business functions to an external provider"]}', NULL, 'sign an outsourcing agreement / outsourcing agreement terms', '[{"en":"The outsourcing agreement covers IT support and data management.","zh-TW":"外包協議涵蓋了IT支援和數據管理。"},{"en":"Service levels are defined in the outsourcing agreement.","zh-TW":"服務水平在外包協議中有所界定。"}]', NULL, NULL, 5, 4707, NULL),
(4708, 'outsourcing contract', '/ˌaʊtˈsɔːrsɪŋ ˈkɒntrækt/', 'noun', '{"zh-TW":["外包合約"],"en":["an agreement for an external party to perform services on behalf of a company"]}', NULL, 'sign an outsourcing contract / outsourcing contract terms', '[{"en":"The outsourcing contract covers IT support for five years.","zh-TW":"外包合約涵蓋五年的IT支援服務。"},{"en":"Penalties were included in the outsourcing contract for service failures.","zh-TW":"外包合約中包含了服務失敗的罰款條款。"}]', NULL, NULL, 5, 4708, NULL),
(4709, 'outstanding', '/aʊtˈstændɪŋ/', 'adjective', '{"zh-TW":["傑出的","未解決的"],"en":["excellent","not yet resolved"]}', '{"prefix":{"text":"out-","meaning":"超出"},"root":{"text":"standing","meaning":"站立"}}', 'outstanding performance / outstanding balance', '[{"en":"She received an award for outstanding performance.","zh-TW":"她因傑出表現獲獎。"},{"en":"There are outstanding invoices.","zh-TW":"有未付的發票。"}]', '{"adverb":"outstandingly"}', NULL, 4, 4709, 168),
(4710, 'outstanding balance', '/ˌaʊtˈstændɪŋ ˈbæləns/', 'noun', '{"zh-TW":["未付餘額；未結清金額"],"en":["the amount of money still owed on a loan or invoice"]}', NULL, 'clear the outstanding balance / outstanding balance due', '[{"en":"The outstanding balance on the invoice was 3000 dollars.","zh-TW":"發票上的未付餘額為3000美元。"},{"en":"Interest accrues daily on the outstanding balance.","zh-TW":"未結清金額每天累積利息。"}]', NULL, NULL, 5, 4710, NULL),
(4711, 'outstanding shares', '/ˌaʊtˈstændɪŋ ʃeərz/', 'noun', '{"zh-TW":["已發行流通股"],"en":["the total number of shares currently held by all shareholders"]}', NULL, 'calculate outstanding shares / reduce outstanding shares', '[{"en":"The company had 10 million outstanding shares before the buyback.","zh-TW":"在回購前，公司有1000萬股已發行流通股。"},{"en":"Earnings per share is calculated using the number of outstanding shares.","zh-TW":"每股盈餘使用已發行流通股數量計算。"}]', NULL, NULL, 5, 4711, NULL),
(4712, 'over', '/ˈoʊvər/', 'adjective, adverb, preposition', '{"zh-TW":["【主要意義-介系詞/副詞】在……上面；超過","【次要意義-形容詞】結束的；完了的","【次要意義-副詞】重新；再次（over again）","【次要意義-副詞】剩餘的；多出的"],"en":["[primary] above; more than; across","[secondary - adjective] finished or ended","[secondary - adverb] once again; repeatedly","[secondary - adverb] remaining after something has been used"]}', NULL, 'it is over / over and above / over and over / left over / once it is over', '[{"en":"Once the fiscal year is over, we will review the budget allocation.","zh-TW":"財政年度結束後，我們將審查預算分配。"},{"en":"Employees were asked to review the policy over and over to ensure compliance.","zh-TW":"員工被要求反覆審查政策以確保合規。"},{"en":"Any funds left over after the project will be returned to the reserve fund.","zh-TW":"專案結束後剩餘的任何資金將歸還給準備金。"}]', '{"noun":"overtime, overhaul","adjective":"overall"}', 'over 作形容詞表「結束的」（it is all over），leftover（剩餘的）、over and above（超出此外）、overall（整體的）均是 TOEIC 商業文章的高頻詞彙。', 1, 4712, NULL),
(4713, 'over-the-counter', '/ˌəʊvər ðə ˈkaʊntər/', 'adjective', '{"zh-TW":["場外交易的"],"en":["traded directly between parties rather than through a formal exchange"]}', NULL, 'over-the-counter market / over-the-counter derivative / over-the-counter drug', '[{"en":"Many derivatives are traded on an over-the-counter basis.","zh-TW":"許多衍生品在場外交易基礎上進行交易。"},{"en":"Over-the-counter markets offer more flexibility but less transparency.","zh-TW":"場外交易市場提供更多靈活性但透明度較低。"}]', NULL, NULL, 5, 4713, NULL),
(4714, 'overall', '/ˌoʊvərˈɔːl/', 'adjective', '{"zh-TW":["整體的；全面的"],"en":["including everything; total"]}', '{"prefix":{"text":"over-","meaning":"全部"},"root":{"text":"all","meaning":"所有"}}', 'overall performance / overall cost', '[{"en":"The overall cost exceeded the budget.","zh-TW":"總成本超出預算。"},{"en":"Overall, results were satisfactory.","zh-TW":"總體而言結果令人滿意。"}]', '{"adverb":"overall"}', NULL, 3, 4714, NULL),
(4715, 'overarching', '/''əʊvərˌɑːrtʃɪŋ/', 'adjective', '{"zh-TW":["總體的；覆蓋一切的"],"en":["forming an arch or covering everything; encompassing; comprehensive"]}', NULL, 'overarching goal / overarching theme / overarching strategy', '[{"en":"The overarching goal of the initiative is to reduce carbon emissions by fifty percent.","zh-TW":"該倡議的總體目標是將碳排放減少百分之五十。"},{"en":"The overarching strategy brought all departments under a single cohesive vision.","zh-TW":"總體策略使所有部門在一個統一的願景下聯合起來。"}]', NULL, NULL, 4, 4715, NULL),
(4716, 'overbook', '/''əʊvərˌbʊk/', 'verb', '{"zh-TW":["超額預訂；超賣"],"en":["to accept more bookings or reservations than there is capacity for"]}', NULL, 'overbook a flight / risk of overbooking / airlines overbook', '[{"en":"The airline overbooked the flight and had to offer compensation to volunteers.","zh-TW":"航空公司超賣了航班，不得不向志願者提供補償。"},{"en":"Hotels sometimes overbook to account for last-minute cancellations.","zh-TW":"飯店有時超額預訂，以應對最後一刻的取消。"}]', '{"noun":"overbooking"}', NULL, 3, 4716, NULL),
(4717, 'overbooking', '/ˌəʊvəˈbʊkɪŋ/', 'noun', '{"zh-TW":["超額預訂"],"en":["the practice of selling more seats than are available"]}', NULL, 'airline overbooking / overbooking policy', '[{"en":"The airline compensated passengers due to overbooking.","zh-TW":"航空公司因超額預訂而賠償乘客。"},{"en":"Overbooking can result in denied boarding for some passengers.","zh-TW":"超額預訂可能導致部分乘客被拒絕登機。"}]', '{"verb":"overbook","adjective":"overbooked"}', NULL, 4, 4717, NULL),
(4718, 'overcapitalized', '/ˌəʊvəˈkæpɪtəlaɪzd/', 'adjective', '{"zh-TW":["資本過剩的"],"en":["having more capital than is needed for efficient operation"]}', NULL, 'overcapitalized company / overcapitalized industry / overcapitalized market', '[{"en":"The overcapitalized industry faced pressure to consolidate.","zh-TW":"資本過剩的行業面臨整合的壓力。"},{"en":"Analysts warned that the firm was overcapitalized and should return cash to shareholders.","zh-TW":"分析師警告說，該公司資本過剩，應將現金回饋給股東。"}]', '{"noun":"overcapitalization","verb":"overcapitalize"}', NULL, 5, 4718, NULL),
(4719, 'overcome', '/ˌoʊvərˈkʌm/', 'verb', '{"zh-TW":["克服","克服；戰勝"],"en":["to succeed in dealing with a problem","to succeed in dealing with difficulty"]}', '{"prefix":{"text":"over-","meaning":"over (越過)"},"root":{"text":"come","meaning":"come (到來)"},"logic":"越過困難而到達，即「克服」。"}', 'overcome obstacles / overcome challenges / overcome fear; overcome difficulties / overcome obstacles', '[{"en":"She overcame many obstacles to succeed.","zh-TW":"她克服了許多障礙才成功。"},{"en":"He is trying to overcome his fear of public speaking.","zh-TW":"他正在試圖克服對公開演講的恐懼。"},{"en":"She overcame many challenges.","zh-TW":"她克服了許多挑戰。"},{"en":"We must overcome these difficulties.","zh-TW":"我們必須克服這些困難。"}]', NULL, NULL, 3, 4719, 704),
(4720, 'overdraft', '/ˈəʊvədrɑːft/', 'noun', '{"zh-TW":["透支；超支"],"en":["a facility allowing spending beyond available bank balance"]}', NULL, 'go into overdraft / overdraft protection', '[{"en":"He accidentally went into overdraft and was charged a fee.","zh-TW":"他不小心透支並被收取了費用。"},{"en":"Overdraft protection prevents transactions from being declined.","zh-TW":"透支保護可防止交易被拒絕。"}]', '{"verb":"overdraw","adjective":"overdrawn"}', NULL, 3, 4720, NULL),
(4721, 'overdue', '/ˌəʊvəˈdjuː/', 'adjective', '{"zh-TW":["逾期的；過期的"],"en":["past the time when it was expected or required"]}', NULL, 'overdue invoice / overdue payment', '[{"en":"The invoice is now 30 days overdue.","zh-TW":"發票現在已逾期30天。"},{"en":"Please settle the overdue balance immediately.","zh-TW":"請立即結清逾期餘額。"}]', NULL, NULL, 3, 4721, NULL),
(4722, 'overdue account', '/ˌoʊvərˈdjuː əˈkaʊnt/', 'noun', '{"zh-TW":["逾期帳戶"],"en":["an account where payment has not been made by the due date"]}', NULL, 'identify overdue accounts / collect on overdue accounts', '[{"en":"All overdue accounts are sent automated payment reminders.","zh-TW":"所有逾期帳戶都會收到自動付款提醒。"},{"en":"The collections team follows up on overdue accounts weekly.","zh-TW":"追收團隊每週跟進逾期帳戶。"}]', NULL, NULL, 5, 4722, NULL),
(4723, 'overdue invoice', '/ˌoʊvərˈdjuː ˈɪnvɔɪs/', 'noun', '{"zh-TW":["逾期發票"],"en":["an invoice that has not been paid by the agreed due date"]}', NULL, 'chase overdue invoices / overdue invoice follow-up', '[{"en":"The accounts team sent reminders for all overdue invoices.","zh-TW":"帳務團隊為所有逾期發票發送了提醒。"},{"en":"An aging report helps prioritize collection of overdue invoices.","zh-TW":"應收帳款賬齡分析報告有助於優先催收逾期發票。"}]', NULL, NULL, 5, 4723, NULL),
(4724, 'overdue payment', '/ˌoʊvərˈdjuː ˈpeɪmənt/', 'noun', '{"zh-TW":["逾期付款；逾期款項"],"en":["a payment not received by the due date"]}', NULL, 'chase overdue payments / overdue payment penalty', '[{"en":"The company sent reminders for all overdue payments weekly.","zh-TW":"公司每週發送所有逾期款項的催款通知。"},{"en":"Late fees are applied on overdue payments after 30 days.","zh-TW":"逾期款項30天後將收取滯納金。"}]', NULL, NULL, 5, 4724, NULL),
(4725, 'overhaul', '/ˈoʊvərhɔːl/', 'noun', '{"zh-TW":["徹底檢修；大改革"],"en":["a thorough examination and repair or revision of something"]}', NULL, 'system overhaul / policy overhaul / complete overhaul', '[{"en":"The IT system underwent a complete overhaul to improve performance.","zh-TW":"IT系統進行了全面翻修以提高性能。"},{"en":"A policy overhaul was announced to align with new regulations.","zh-TW":"宣佈進行政策大改革以符合新法規。"}]', '{"verb":"overhaul","adjective":"overhauled"}', NULL, 3, 4725, NULL),
(4726, 'overhead', '/ˈoʊvərˌhɛd/', 'noun', '{"zh-TW":["管理費用；經常性開支"],"en":["ongoing business expenses not directly tied to production"]}', NULL, 'overhead costs / reduce overhead', '[{"en":"We need to reduce overhead costs.","zh-TW":"我們需要降低管理費用。"},{"en":"Rent is our biggest overhead expense.","zh-TW":"租金是我們最大的經常性開支。"}]', '{"noun":"overhead","adjective":"overhead"}', NULL, 3, 4726, 406),
(4727, 'overhead allocation', '/ˈoʊvərhed ˌæləˈkeɪʃən/', 'noun', '{"zh-TW":["間接費用分配"],"en":["the process of distributing overhead costs across products or departments"]}', NULL, 'allocate overhead / overhead allocation method', '[{"en":"Overhead allocation ensures all departments share indirect costs fairly.","zh-TW":"間接費用分配確保所有部門公平分擔間接成本。"},{"en":"The accounting team revised the overhead allocation formula.","zh-TW":"會計團隊修訂了間接費用分配公式。"}]', NULL, NULL, 5, 4727, NULL),
(4728, 'overhead bin', '/ˈoʊvərˌhɛd bɪn/', 'noun', '{"zh-TW":["頭頂置物箱"],"en":["the storage compartment above seats in an aircraft"]}', NULL, 'place in the overhead bin / open the overhead bin', '[{"en":"Please store your carry-on in the overhead bin.","zh-TW":"請將手提行李放入頭頂置物箱。"},{"en":"The overhead bins are full on this flight.","zh-TW":"這架航班的頭頂置物箱已滿。"}]', NULL, NULL, 4, 4728, NULL),
(4729, 'overhead compartment', '/''əʊvəhed kəmˈpɑːtmənt/', 'noun', '{"zh-TW":["行李艙；頭頂置物箱"],"en":["a storage space above passenger seats in an aircraft for stowing carry-on luggage"]}', NULL, 'stow in the overhead compartment / full overhead compartment', '[{"en":"Please ensure your carry-on bag fits in the overhead compartment.","zh-TW":"請確保您的隨身行李能放入頭頂置物箱。"},{"en":"The overhead compartment was full, so he stored his bag under the seat.","zh-TW":"頭頂置物箱已滿，所以他把包放在座位下面。"}]', NULL, NULL, 5, 4729, NULL),
(4730, 'overhead cost', '/ˈoʊvərhed kɒst/', 'noun', '{"zh-TW":["間接成本；管理費用"],"en":["ongoing operational expenses not directly linked to production"]}', NULL, 'reduce overhead costs / fixed overhead / overhead cost allocation', '[{"en":"The company cut overhead costs by moving to a smaller office.","zh-TW":"公司通過遷往較小辦公室降低了間接成本。"},{"en":"Overhead costs must be factored into the product pricing.","zh-TW":"計算產品定價時必須考慮間接成本。"}]', NULL, NULL, 5, 4730, NULL),
(4731, 'overhead costs', '/ˈəʊvəhɛd kɒsts/', 'noun', '{"zh-TW":["間接費用；管理費用"],"en":["ongoing business expenses not related to direct production"]}', NULL, 'reduce overhead costs / overhead cost analysis', '[{"en":"The company cut overhead costs by switching to remote work.","zh-TW":"公司透過轉向遠端工作降低了間接費用。"},{"en":"Overhead costs include rent, utilities, and administrative salaries.","zh-TW":"間接費用包括租金、水電費和行政薪資。"}]', NULL, NULL, 5, 4731, NULL),
(4732, 'overhead expenses', '/ˈəʊvəhed ɪkˈspensɪz/', 'noun', '{"zh-TW":["管理費用；間接支出"],"en":["ongoing costs of running a business that are not directly tied to creating a product or service"]}', NULL, 'manage overhead expenses / reduce overhead expenses / overhead expenses budget', '[{"en":"Rent, utilities, and administrative salaries are all considered overhead expenses.","zh-TW":"租金、水電費和行政薪資都被視為管理費用。"},{"en":"Controlling overhead expenses is essential for maintaining healthy profit margins.","zh-TW":"控制管理費用對於維持健康的利潤率至關重要。"}]', '{"adjective":"overhead"}', NULL, 5, 4732, NULL),
(4733, 'overhead projector', '/ˈəʊvərˌhɛd prəˈdʒɛktər/', 'noun', '{"zh-TW":["投影機；投影儀"],"en":["a device used to project images onto a screen for presentations"]}', NULL, 'use an overhead projector / overhead projector presentation', '[{"en":"The meeting room has a new overhead projector.","zh-TW":"會議室有一台新的投影機。"},{"en":"The trainer used an overhead projector to display the slides.","zh-TW":"培訓師使用投影機展示投影片。"}]', NULL, NULL, 5, 4733, NULL),
(4734, 'overhead reduction', '/''əʊvəhed rɪˌdʌkʃən/', 'noun', '{"zh-TW":["間接費用削減；管理費用降低"],"en":["a decrease in the ongoing business expenses not directly tied to production"]}', NULL, 'achieve overhead reduction / overhead reduction strategy / overhead reduction target', '[{"en":"The restructuring plan aimed for a twenty percent overhead reduction within two years.","zh-TW":"重組計劃旨在兩年內實現二十%的間接費用削減。"},{"en":"Overhead reduction can significantly boost a company''s profitability without affecting output.","zh-TW":"間接費用削減可以在不影響產量的情況下顯著提升公司的盈利能力。"}]', '{"verb":"reduce","noun2":"reduction"}', NULL, 5, 4734, NULL),
(4735, 'overheads', '/ˈoʊvərhedz/', 'noun', '{"zh-TW":["間接費用；管理費用"],"en":["the general costs of running a business not tied to specific products"]}', NULL, 'reduce overheads / fixed overheads / high overheads', '[{"en":"Reducing overheads by moving to a smaller office saved 200000 annually.","zh-TW":"通過搬至更小的辦公室降低間接費用每年節省了20萬元。"},{"en":"Overheads include utilities, rent, and administrative salaries.","zh-TW":"間接費用包括水電費、租金和行政薪資。"}]', NULL, NULL, 3, 4735, NULL),
(4736, 'overland journey', '/''əʊvəlænd ˌdʒɜːrni/', 'noun', '{"zh-TW":["陸路旅行；越野之旅"],"en":["a journey made across land rather than by sea or air"]}', NULL, 'plan an overland journey / embark on an overland journey', '[{"en":"They undertook an overland journey across Central Asia by train.","zh-TW":"他們乘火車進行了穿越中亞的陸路旅行。"},{"en":"An overland journey allows travelers to experience the landscape and culture more deeply.","zh-TW":"陸路旅行讓旅行者能更深入地體驗地形和文化。"}]', NULL, NULL, 5, 4736, NULL),
(4737, 'overland travel', '/''əʊvəlænd ˌtrævəl/', 'noun', '{"zh-TW":["陸路旅行"],"en":["travel across land rather than by sea or air, often through multiple regions or countries"]}', NULL, 'plan overland travel / overland travel route / adventure overland travel', '[{"en":"They chose overland travel to experience the landscape and local culture more deeply.","zh-TW":"他們選擇陸路旅行，以更深入地體驗地形和當地文化。"},{"en":"Overland travel in Africa can be challenging but incredibly rewarding.","zh-TW":"在非洲的陸路旅行可能充滿挑戰，但卻非常值得。"}]', NULL, NULL, 5, 4737, NULL),
(4738, 'overlook', '/ˌoʊvərˈlʊk/', 'verb', '{"zh-TW":["忽略","俯瞰"],"en":["to fail to notice","to have a view over"]}', '{"prefix":{"text":"over-","meaning":"over"},"root":{"text":"look","meaning":"看"}}', 'overlook a detail / easily overlooked', '[{"en":"Don''t overlook the fine print.","zh-TW":"別忽略小字。"},{"en":"This detail was overlooked.","zh-TW":"這個細節被忽視了。"}]', NULL, NULL, 3, 4738, NULL),
(4739, 'overnight stay', '/''əʊvənaɪt steɪ/', 'noun', '{"zh-TW":["過夜住宿；一夜停留"],"en":["a stay lasting one night at a particular place"]}', NULL, 'arrange an overnight stay / overnight stay included / overnight stay package', '[{"en":"The travel package included an overnight stay at a four-star hotel.","zh-TW":"這個旅遊套餐包含在四星級飯店的一夜住宿。"},{"en":"An overnight stay in a traditional inn is a cultural experience not to be missed.","zh-TW":"在傳統旅館的一夜住宿是不容錯過的文化體驗。"}]', NULL, NULL, 5, 4739, NULL),
(4740, 'override', '/ˌoʊvərˈraɪd/', 'verb', '{"zh-TW":["推翻；凌駕"],"en":["to use authority to cancel or reverse a decision made by someone else"]}', NULL, 'override a decision / override a system / override authority', '[{"en":"The senior manager overrode the department head''s approval.","zh-TW":"高級經理推翻了部門主管的批准決定。"},{"en":"An administrator can override default system settings.","zh-TW":"管理員可以覆蓋系統默認設置。"}]', '{"noun":"override"}', NULL, 3, 4740, NULL),
(4741, 'overrun', '/ˈoʊvərʌn/', 'noun', '{"zh-TW":["超支；超時"],"en":["an amount by which costs or time exceed the planned budget or schedule"]}', NULL, 'budget overrun / time overrun', '[{"en":"The construction project experienced a 15% cost overrun.","zh-TW":"建設項目出現了15%的成本超支。"},{"en":"Overruns on major projects require board approval for additional funding.","zh-TW":"主要項目的超支需要董事會批准額外資金。"}]', '{"verb":"overrun"}', NULL, 3, 4741, NULL),
(4742, 'overseas', '/ˌoʊvərˈsiːz/', 'adverb', '{"zh-TW":["海外的"],"en":["in a foreign country"]}', '{"prefix":{"text":"over-","meaning":"越過"},"root":{"text":"seas","meaning":"海洋"}}', 'overseas market / go overseas', '[{"en":"The company is expanding overseas.","zh-TW":"公司正在海外擴展。"},{"en":"Many graduates seek employment overseas.","zh-TW":"許多畢業生在海外求職。"}]', NULL, NULL, 3, 4742, NULL),
(4743, 'oversee', '/ˌəʊvəˈsiː/', 'verb', '{"zh-TW":["監督；管理"],"en":["to watch over and direct an activity or process"]}', NULL, 'oversee operations / oversee a project', '[{"en":"He was appointed to oversee the construction project.","zh-TW":"他被任命監督建設項目。"},{"en":"The manager oversees a team of twenty employees.","zh-TW":"經理監督一個由二十名員工組成的團隊。"}]', '{"noun":"oversight","noun2":"overseer","adjective":"overseen"}', NULL, 3, 4743, 407),
(4744, 'oversight', '/ˈoʊvərsaɪt/', 'noun', '{"zh-TW":["監督；疏忽"],"en":["supervision and control of a process or organization; also an accidental omission"]}', NULL, 'provide oversight / regulatory oversight / management oversight', '[{"en":"The board has oversight responsibility for the risk management framework.","zh-TW":"董事會對風險管理框架負有監督責任。"},{"en":"The error was due to an oversight in the review process.","zh-TW":"這個錯誤是由於審查過程中的疏忽造成的。"}]', '{"verb":"oversee","adjective":"overseen"}', NULL, 3, 4744, 899),
(4745, 'overstock', '/ˈoʊvərstɒk/', 'noun', '{"zh-TW":["過剩庫存；超額庫存"],"en":["having more inventory than is needed to meet current demand"]}', NULL, 'deal with overstock / reduce overstock', '[{"en":"Overstocking ties up capital and increases storage costs.","zh-TW":"過剩庫存佔用資本並增加倉儲成本。"},{"en":"The retailer discounted items to clear overstock before the season ended.","zh-TW":"零售商在季節結束前打折清理過剩庫存。"}]', '{"verb":"overstock","adjective":"overstocked"}', NULL, 3, 4745, NULL),
(4746, 'oversubscribed', '/ˌəʊvəsəbˈskraɪbd/', 'adjective', '{"zh-TW":["超額認購的"],"en":["(of an issue of shares or bonds) having more applications than available"]}', NULL, 'oversubscribed offering / heavily oversubscribed / book is oversubscribed', '[{"en":"The IPO was ten times oversubscribed, reflecting strong investor demand.","zh-TW":"IPO超額認購十倍，反映了投資者的強烈需求。"},{"en":"Oversubscribed deals allow issuers to price at a premium.","zh-TW":"超額認購的交易允許發行人以溢價定價。"}]', NULL, NULL, 5, 4746, NULL),
(4747, 'overtime', '/ˈoʊvərtaɪm/', 'noun', '{"zh-TW":["加班"],"en":["time worked beyond normal hours"]}', '{"prefix":{"text":"over-","meaning":"超過"},"root":{"text":"time","meaning":"時間"}}', 'work overtime / overtime pay', '[{"en":"Employees are paid extra for overtime.","zh-TW":"員工加班有額外報酬。"},{"en":"She works overtime to meet deadlines.","zh-TW":"她加班趕截止日期。"}]', NULL, NULL, 3, 4747, NULL),
(4748, 'overtime pay', '/ˈoʊvərtaɪm peɪ/', 'noun', '{"zh-TW":["加班費"],"en":["additional compensation for hours worked beyond the regular work schedule"]}', NULL, 'receive overtime pay / calculate overtime pay', '[{"en":"Employees are entitled to overtime pay at 1.5 times the regular rate.","zh-TW":"員工有權獲得按正常費率1.5倍計算的加班費。"},{"en":"The company limited overtime pay by hiring temporary staff.","zh-TW":"公司通過聘用臨時員工限制了加班費。"}]', NULL, NULL, 4, 4748, NULL),
(4749, 'overtraining', '/''əʊvərˌtreɪnɪŋ/', 'noun', '{"zh-TW":["過度訓練"],"en":["training too hard without adequate recovery time, leading to decreased performance and injury risk"]}', NULL, 'risk of overtraining / avoid overtraining / symptoms of overtraining', '[{"en":"Overtraining can lead to fatigue, injury, and a drop in performance.","zh-TW":"過度訓練可能導致疲勞、受傷和成績下降。"},{"en":"Rest days are crucial for athletes to avoid the negative effects of overtraining.","zh-TW":"休息日對運動員避免過度訓練的負面影響至關重要。"}]', '{"verb":"overtrain"}', NULL, 4, 4749, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4750, 'overvaluation', '/ˌəʊvəˌvæljuˈeɪʃən/', 'noun', '{"zh-TW":["高估；估值過高"],"en":["the assignment of too high a value to an asset"]}', NULL, 'detect overvaluation / stock market overvaluation / correct overvaluation', '[{"en":"Overvaluation in the tech sector preceded the 2000 market crash.","zh-TW":"科技行業的高估先於2000年的市場崩盤。"},{"en":"Currency overvaluation harms exporters by making their goods more expensive abroad.","zh-TW":"貨幣高估通過使本國商品在國外更昂貴而損害出口商。"}]', '{"verb":"overvalue","adjective":"overvalued"}', NULL, 5, 4750, NULL),
(4751, 'overvalue', '/ˌoʊvərˈvæljuː/', 'verb', '{"zh-TW":["高估；定價過高"],"en":["to place too high a value on something"]}', NULL, 'overvalue an asset / stock is overvalued', '[{"en":"Analysts warned the stock was overvalued at current prices.","zh-TW":"分析師警告股票在當前價格下被高估了。"},{"en":"An overvalued currency makes exports less competitive.","zh-TW":"高估的貨幣使出口競爭力下降。"}]', '{"noun":"overvaluation","adjective":"overvalued"}', NULL, 3, 4751, NULL),
(4752, 'overview', '/ˈoʊvərvjuː/', 'noun', '{"zh-TW":["概述；總覽"],"en":["a general summary"]}', '{"prefix":{"text":"over-","meaning":"全面"},"root":{"text":"view","meaning":"看"}}', 'brief overview / overview of the project', '[{"en":"The report provides an overview of trends.","zh-TW":"報告提供了趨勢概述。"},{"en":"Let me give a brief overview.","zh-TW":"讓我簡要概述。"}]', NULL, NULL, 3, 4752, 169),
(4753, 'overwhelm', '/ˌoʊvərˈwɛlm/', 'verb', '{"zh-TW":["壓倒；使不知所措"],"en":["to be too much to deal with"]}', '{"prefix":{"text":"over-","meaning":"過度"},"root":{"text":"whelm","meaning":"submerge (淹沒)"}}', 'be overwhelmed by / overwhelming majority', '[{"en":"She was overwhelmed by the workload.","zh-TW":"她被工作量壓垮了。"},{"en":"The response was overwhelming.","zh-TW":"反應非常熱烈。"}]', '{"adjective":"overwhelming, overwhelmed","adverb":"overwhelmingly"}', NULL, 3, 4753, NULL),
(4754, 'owe', '/oʊ/', 'verb', '{"zh-TW":["欠","歸功於"],"en":["to need to pay back","to have because of help"]}', NULL, 'owe money / owe sb. a favor', '[{"en":"The company owes $5 million.","zh-TW":"公司欠五百萬美元。"},{"en":"I owe my success to my mentor.","zh-TW":"我的成功歸功於導師。"}]', NULL, NULL, 1, 4754, NULL),
(4755, 'own resources', '/oʊn rɪˈsɔːrsɪz/', 'noun', '{"zh-TW":["自有資源；自有資金"],"en":["internally generated funds used to finance activities without borrowing"]}', NULL, 'fund with own resources / rely on own resources', '[{"en":"The company funded the project using its own resources.","zh-TW":"公司使用自有資源資助了該項目。"},{"en":"Relying on own resources avoids taking on additional debt.","zh-TW":"依靠自有資源避免了承擔額外債務。"}]', NULL, NULL, 5, 4755, NULL),
(4756, 'owner''s equity', '/ˈoʊnərz ˈekwɪti/', 'noun', '{"zh-TW":["業主權益"],"en":["the owner''s residual interest in the business after liabilities are deducted"]}', NULL, 'calculate owner''s equity / growing owner''s equity', '[{"en":"A positive owner''s equity means assets exceed liabilities.","zh-TW":"正的業主權益意味著資產超過負債。"},{"en":"Owner''s equity increases when the business retains profits.","zh-TW":"當企業保留利潤時，業主權益增加。"}]', NULL, NULL, 5, 4756, NULL),
(4757, 'owner-operator', '/ˈoʊnər ˈɒpəreɪtər/', 'noun', '{"zh-TW":["業主兼經營者"],"en":["a person who both owns and runs a business"]}', NULL, 'independent owner-operator / owner-operator model', '[{"en":"The franchise is run by an owner-operator with 10 years experience.","zh-TW":"特許經營由一名擁有10年經驗的業主兼經營者管理。"},{"en":"Owner-operators are strongly motivated to succeed.","zh-TW":"業主兼經營者有強烈的成功動機。"}]', NULL, NULL, 5, 4757, NULL),
(4758, 'ownership', '/ˈəʊnərʃɪp/', 'noun', '{"zh-TW":["所有權；擁有"],"en":["the fact of owning something"]}', NULL, 'transfer of ownership / sole ownership', '[{"en":"The transfer of ownership was completed last month.","zh-TW":"所有權轉讓上個月完成了。"},{"en":"She took ownership of the project and delivered excellent results.","zh-TW":"她承擔了項目的責任並交出了出色的成果。"}]', '{"verb":"own","noun":"owner","adjective":"owned"}', NULL, 3, 4758, NULL),
(4759, 'ownership structure', '/ˈoʊnərʃɪp ˈstrʌktʃər/', 'noun', '{"zh-TW":["所有權結構"],"en":["the way in which ownership of a company is divided among shareholders"]}', NULL, 'review ownership structure / ownership structure disclosure', '[{"en":"The ownership structure was disclosed in the company prospectus.","zh-TW":"所有權結構在公司招股書中披露了。"},{"en":"A complex ownership structure can complicate governance.","zh-TW":"複雜的所有權結構可能使治理複雜化。"}]', NULL, NULL, 5, 4759, NULL),
(4760, 'ozone depletion', '/ˈəʊzəʊn dɪˈpliːʃən/', 'noun', '{"zh-TW":["臭氧層耗損"],"en":["the thinning of the Earth''s ozone layer due to chemical pollutants"]}', NULL, 'prevent ozone depletion / ozone depletion causes / ozone depletion effects', '[{"en":"The Montreal Protocol successfully reduced ozone depletion.","zh-TW":"蒙特婁議定書成功減少了臭氧層耗損。"},{"en":"Ozone depletion increases UV radiation reaching the Earth''s surface.","zh-TW":"臭氧層耗損增加了到達地球表面的紫外線輻射。"}]', '{"verb":"deplete","adjective":"depleted"}', NULL, 5, 4760, NULL),
(4761, 'ozone layer', '/ˈəʊzəʊn ˈleɪər/', 'noun', '{"zh-TW":["臭氧層"],"en":["a layer of ozone in the stratosphere that protects the Earth"]}', NULL, 'protect the ozone layer / ozone layer depletion', '[{"en":"Chemicals like CFCs have damaged the ozone layer.","zh-TW":"氟氯碳化物等化學物質破壞了臭氧層。"},{"en":"International agreements have helped slow ozone layer depletion.","zh-TW":"國際協議有助於減緩臭氧層耗損。"}]', NULL, NULL, 4, 4761, NULL),
(4762, 'pace', '/peɪs/', 'noun', '{"zh-TW":["步伐；速度"],"en":["the speed of movement or activity"]}', NULL, 'at a fast pace / keep pace with / set the pace', '[{"en":"The pace of technological change is rapid.","zh-TW":"技術變革的步伐很快。"},{"en":"We need to keep pace with competitors.","zh-TW":"我們需要跟上競爭對手。"}]', '{"verb":"pace"}', NULL, 1, 4762, NULL),
(4763, 'package', '/ˈpækɪdʒ/', 'noun', '{"zh-TW":["包裹","套裝；方案"],"en":["a wrapped object","a set of things offered together"]}', NULL, 'compensation package / package deal', '[{"en":"The package was delivered this morning.","zh-TW":"包裹今早送達了。"},{"en":"They offered an attractive compensation package.","zh-TW":"他們提供了優厚的薪酬方案。"}]', '{"verb":"package","noun":"packaging"}', NULL, 3, 4763, 408),
(4764, 'package deal', '/ˈpækɪdʒ diːl/', 'noun', '{"zh-TW":["套裝方案；一攬子交易"],"en":["an offer combining several elements that must be accepted together"]}', NULL, 'accept a package deal / offer a package deal', '[{"en":"The supplier offered a package deal including installation and training.","zh-TW":"供應商提供了包括安裝和培訓的套裝方案。"},{"en":"Negotiators agreed on a package deal covering wages and benefits.","zh-TW":"談判者就包含薪資和福利的一攬子交易達成了協議。"}]', NULL, NULL, 4, 4764, NULL),
(4765, 'package tour', '/ˈpækɪdʒ tʊər/', 'noun', '{"zh-TW":["套裝行程"],"en":["a vacation with transport and accommodation arranged together"]}', NULL, 'book a package tour / all-inclusive package tour', '[{"en":"They chose a package tour to save money on their vacation.","zh-TW":"他們選擇套裝行程以節省度假費用。"},{"en":"The package tour includes hotel, meals, and guided tours.","zh-TW":"套裝行程包含飯店、餐食和導覽。"}]', NULL, NULL, 4, 4765, NULL),
(4766, 'packaging', '/ˈpækɪdʒɪŋ/', 'noun', '{"zh-TW":["包裝"],"en":["materials used to wrap or protect goods"]}', '{"root":{"text":"pack","meaning":"bundle (打包)"},"suffix":{"text":"-aging","meaning":"process of (過程)"},"logic":"打包的過程或材料，即「包裝」。"}', 'eco-friendly packaging / product packaging', '[{"en":"The packaging was damaged during shipping.","zh-TW":"包裝在運送過程中受損。"},{"en":"We use eco-friendly packaging materials.","zh-TW":"我們使用環保包裝材料。"}]', '{"verb":"package","noun":"package"}', NULL, 3, 4766, NULL),
(4767, 'packaging material', '/''pækɪdʒɪŋ məˌtɪəriəl/', 'noun', '{"zh-TW":["包裝材料"],"en":["materials used to wrap, protect, or contain products for storage and transportation"]}', NULL, 'choose packaging material / sustainable packaging material / packaging material cost', '[{"en":"She selected biodegradable packaging materials to reduce the company''s environmental impact.","zh-TW":"她選擇了可生物降解的包裝材料，以減少公司的環境影響。"},{"en":"Using the right packaging material prevents damage to goods during transit.","zh-TW":"使用正確的包裝材料可以防止貨物在運輸過程中損壞。"}]', NULL, NULL, 5, 4767, NULL),
(4768, 'packing list', '/''pækɪŋ lɪst/', 'noun', '{"zh-TW":["打包清單；行李清單"],"en":["a list of items to pack for a trip"]}', NULL, 'prepare a packing list / follow a packing list / comprehensive packing list', '[{"en":"She always makes a detailed packing list before every international trip.","zh-TW":"她每次國際旅行前都會製作一份詳細的打包清單。"},{"en":"A good packing list ensures you don''t forget any essential items.","zh-TW":"一份好的打包清單確保你不會忘記任何必需品。"}]', NULL, NULL, 4, 4768, NULL),
(4769, 'page', '/peɪdʒ/', 'noun', '{"zh-TW":["頁面；網頁"],"en":["one side of a sheet of paper","a section of a website"]}', NULL, 'home page / on the same page', '[{"en":"Let''s make sure we are on the same page.","zh-TW":"讓我們確認彼此有共識。"},{"en":"Visit our web page for more details.","zh-TW":"請瀏覽我們的網頁了解更多。"}]', '{"noun":"page","noun2":"webpage"}', NULL, 1, 4769, NULL),
(4770, 'paid leave', '/peɪd liːv/', 'noun', '{"zh-TW":["有薪假期"],"en":["time off from work for which the employee continues to receive pay"]}', NULL, 'take paid leave / paid leave entitlement', '[{"en":"Employees are entitled to 14 days of paid leave annually.","zh-TW":"員工每年有14天的有薪假期。"},{"en":"Maternity leave is provided as paid leave under company policy.","zh-TW":"育嬰假根據公司政策作為有薪假期提供。"}]', NULL, NULL, 4, 4770, NULL),
(4771, 'paid search', '/peɪd sɜːrtʃ/', 'noun', '{"zh-TW":["付費搜尋廣告"],"en":["advertising model where companies pay to appear in search results"]}', NULL, 'paid search campaign / paid search ads / paid search optimization', '[{"en":"Paid search delivered immediate traffic to the newly launched site.","zh-TW":"付費搜尋廣告為新推出的網站立即帶來了流量。"},{"en":"Paid search and organic SEO should work together for maximum impact.","zh-TW":"付費搜尋和自然SEO應一起發揮最大效果。"}]', NULL, NULL, 4, 4771, NULL),
(4772, 'paid time off', '/peɪd taɪm ɒf/', 'noun', '{"zh-TW":["有薪假期"],"en":["leave days for which an employee continues to receive pay"]}', NULL, 'accrue paid time off / use paid time off / paid time off policy', '[{"en":"Employees receive 20 days of paid time off per year.","zh-TW":"員工每年有20天有薪假期。"},{"en":"She used her paid time off to travel abroad.","zh-TW":"她用有薪假期出國旅遊。"}]', '{"abbreviation":"PTO"}', NULL, 5, 4772, NULL),
(4773, 'paid-in capital', '/peɪd ɪn ˈkæpɪtəl/', 'noun', '{"zh-TW":["已繳入資本；實收資本"],"en":["the total amount of capital contributed by shareholders in exchange for shares"]}', NULL, 'increase paid-in capital / paid-in capital balance', '[{"en":"Paid-in capital increased following the rights issue to existing shareholders.","zh-TW":"在向現有股東配股後，已繳入資本增加了。"},{"en":"The paid-in capital account records proceeds from share issuance at par and premium.","zh-TW":"已繳入資本帳戶記錄了面值和溢價發行股份的收益。"}]', NULL, NULL, 5, 4773, NULL),
(4774, 'paid-up capital', '/ˌpeɪd ʌp ˈkæpɪtəl/', 'noun', '{"zh-TW":["實收資本"],"en":["the amount of money a company has received from shareholders in exchange for shares"]}', NULL, 'increase paid-up capital / paid-up capital requirement', '[{"en":"The company increased its paid-up capital to meet regulatory requirements.","zh-TW":"公司增加了實收資本以滿足監管要求。"},{"en":"Paid-up capital represents the actual investment made by shareholders.","zh-TW":"實收資本代表了股東的實際投資。"}]', NULL, NULL, 5, 4774, NULL),
(4775, 'pain', '/peɪn/', 'noun', '{"zh-TW":["痛苦；疼痛"],"en":["physical suffering","mental distress"]}', NULL, 'pain point / no pain no gain', '[{"en":"We identified the customer''s pain points.","zh-TW":"我們找出了客戶的痛點。"},{"en":"No pain, no gain in business.","zh-TW":"商場上不吃苦就沒有收穫。"}]', '{"noun":"pain","adjective":"painful","adjective2":"painless","adverb":"painfully"}', NULL, 1, 4775, NULL),
(4776, 'paint', '/peɪnt/', 'verb', '{"zh-TW":["油漆；繪畫"],"en":["to apply color to a surface","to create a picture"]}', NULL, 'paint a picture / fresh paint', '[{"en":"Let me paint a picture of our vision.","zh-TW":"讓我描繪我們的願景。"},{"en":"The office walls need fresh paint.","zh-TW":"辦公室牆壁需要重新粉刷。"}]', '{"verb":"paint","noun":"paint","noun2":"painter","noun3":"painting"}', NULL, 2, 4776, NULL),
(4777, 'palate', '/''pælɪt/', 'noun', '{"zh-TW":["味覺；口味偏好"],"en":["a person''s ability to distinguish different flavors in food and drink"]}', NULL, 'develop a palate / sophisticated palate / train your palate', '[{"en":"Wine tasting classes can help develop a more refined palate.","zh-TW":"品酒課程可以幫助培養更精緻的味覺。"},{"en":"Her extensive travels developed a palate for diverse international cuisines.","zh-TW":"她廣泛的旅行使她培養了對多元國際菜系的口味偏好。"}]', NULL, NULL, 2, 4777, NULL),
(4778, 'palette', '/ˈpælɪt/', 'noun', '{"zh-TW":["調色盤；色彩範圍"],"en":["a board for mixing paints","a range of colors used"]}', '{"root":{"text":"palette","meaning":"small blade (小板子)"},"logic":"源自法語，指畫家用來混合顏料的小板子。"}', 'color palette / artist''s palette', '[{"en":"The artist mixed colors on her palette.","zh-TW":"藝術家在調色盤上混合顏色。"},{"en":"The designer chose a warm color palette.","zh-TW":"設計師選擇了暖色調色盤。"}]', NULL, NULL, 3, 4778, NULL),
(4779, 'pallet', '/''pælɪt/', 'noun', '{"zh-TW":["棧板；托盤"],"en":["a flat wooden or plastic structure used for stacking, storing, and transporting goods in a warehouse"]}', NULL, 'stack on a pallet / wrap a pallet / pallet size', '[{"en":"Forklifts are used to move pallets of goods efficiently around the warehouse.","zh-TW":"叉車用於在倉庫中有效地搬運棧板上的貨物。"},{"en":"The supplier shipped the goods on twelve pallets wrapped in shrink wrap.","zh-TW":"供應商將貨物放在十二個用收縮膜包裹的棧板上運送。"}]', NULL, NULL, 2, 4779, NULL),
(4780, 'palliative care', '/ˈpæliətɪv keər/', 'noun', '{"zh-TW":["緩和醫療；姑息治療"],"en":["medical care focused on relieving suffering and improving quality of life for terminally ill patients"]}', NULL, 'palliative care team / receive palliative care / palliative care approach', '[{"en":"Palliative care focuses on comfort rather than curative treatment.","zh-TW":"緩和醫療側重於舒適而非治癒性治療。"},{"en":"Expanding palliative care services improves end-of-life experiences.","zh-TW":"擴展緩和醫療服務改善了臨終體驗。"}]', '{"adjective":"palliative"}', NULL, 5, 4780, NULL),
(4781, 'panel', '/ˈpænəl/', 'noun', '{"zh-TW":["專家小組","面板"],"en":["a group of experts","a flat surface"]}', NULL, 'panel discussion / solar panel / panel of judges', '[{"en":"A panel of experts discussed the issue.","zh-TW":"一組專家討論了這問題。"},{"en":"The company installed solar panels.","zh-TW":"公司安裝了太陽能板。"}]', '{"noun":"panelist"}', NULL, 2, 4781, NULL),
(4782, 'panel discussion', '/ˈpænəl dɪˈskʌʃən/', 'noun', '{"zh-TW":["小組討論；座談"],"en":["a formal discussion by a group of experts before an audience"]}', NULL, 'participate in a panel discussion / panel discussion topic', '[{"en":"She participated in a panel discussion on renewable energy.","zh-TW":"她參加了一場關於可再生能源的小組討論。"},{"en":"The panel discussion provided diverse perspectives on the issue.","zh-TW":"小組討論提供了關於這個問題的多元觀點。"}]', NULL, NULL, 5, 4782, NULL),
(4783, 'paper', '/ˈpeɪpər/', 'noun', '{"zh-TW":["【主要意義-名詞】紙；報紙","【次要意義-形容詞】表面上的；名義上的；紙面上的","【次要意義-名詞】學術論文；政策文件"],"en":["[primary - noun] thin material used for writing or printing","[secondary - adjective] existing only in theory; not having real substance","[secondary - noun] an academic article or a policy document"]}', NULL, 'paper profit / paper qualifications / on paper / position paper / white paper', '[{"en":"The merger looked great on paper but failed in practice.","zh-TW":"這次合併在紙面上看起來很好，但實際上卻失敗了。"},{"en":"The company reported paper profits due to asset revaluation.","zh-TW":"由於資產重估，公司報告了帳面利潤。"},{"en":"She presented a research paper on consumer behavior at the conference.","zh-TW":"她在會議上發表了一篇關於消費者行為的研究論文。"}]', '{"verb":"paper over","noun":"paperwork"}', 'paper 作形容詞意為「名義上的/帳面上的」（如 paper profit = 帳面利潤），on paper = 理論上，這些是 TOEIC 財務或商業文章的常見陷阱表達。', 2, 4783, NULL),
(4784, 'paperwork', '/ˈpeɪpərwɜːrk/', 'noun', '{"zh-TW":["文書工作；書面工作"],"en":["routine work involving completing and handling documents"]}', NULL, 'complete paperwork / reduce paperwork', '[{"en":"Please complete all required paperwork before your first day.","zh-TW":"請在您上班的第一天前完成所有必要的文書工作。"},{"en":"Digital systems have helped reduce time spent on paperwork.","zh-TW":"數位系統幫助減少了在文書工作上花費的時間。"}]', NULL, NULL, 3, 4784, NULL),
(4785, 'par value', '/pɑːr ˈvæljuː/', 'noun', '{"zh-TW":["面值；票面價值"],"en":["the nominal value of a share or bond as stated on the certificate"]}', NULL, 'trade at par value / above par value / below par value', '[{"en":"The bond pays interest based on its par value regardless of the current market price.","zh-TW":"債券根據其面值支付利息，不論當前市場價格如何。"},{"en":"When a bond trades below its par value, investors earn a yield above the coupon rate.","zh-TW":"當債券以低於面值的價格交易時，投資者賺取高於票面利率的收益率。"}]', NULL, NULL, 3, 4785, NULL),
(4786, 'paradigm', '/ˈpærədaɪm/', 'noun', '{"zh-TW":["典範；範式"],"en":["a typical example or model","a framework of thinking"]}', NULL, 'paradigm shift / new paradigm', '[{"en":"AI represents a paradigm shift in business.","zh-TW":"AI代表著商業的典範轉移。"},{"en":"We need a new paradigm for customer service.","zh-TW":"我們需要客戶服務的新典範。"}]', '{"noun":"paradigm","adjective":"paradigmatic"}', NULL, 3, 4786, NULL),
(4787, 'paradigm example', '/ˈpærəˌdɑɪm ɪɡˈzɑːmpəl/', 'noun', '{"zh-TW":["典範例子；模範示例"],"en":["a perfect or representative example that clearly illustrates a concept or principle"]}', NULL, 'serve as a paradigm example / provide a paradigm example / classic paradigm example', '[{"en":"The company''s turnaround story is often cited as a paradigm example of effective leadership.","zh-TW":"該公司的逆轉故事常被引用為有效領導力的典範例子。"},{"en":"This experiment serves as a paradigm example of the scientific method applied correctly.","zh-TW":"這個實驗作為正確應用科學方法的典範例子。"}]', NULL, NULL, 5, 4787, NULL),
(4788, 'paradigm shift', '/ˈpærəˌdaɪm ʃɪft/', 'noun', '{"zh-TW":["典範轉移；思維方式轉變"],"en":["a fundamental change in approach or underlying assumptions"]}', NULL, 'drive a paradigm shift / experience a paradigm shift', '[{"en":"Remote work caused a paradigm shift in office culture.","zh-TW":"遠端工作引起了辦公室文化的典範轉移。"},{"en":"The digital revolution brought about a paradigm shift in retail.","zh-TW":"數位革命帶來了零售業的典範轉移。"}]', NULL, NULL, 5, 4788, NULL),
(4789, 'paradigmatic', '/ˌpærədɪɡˈmætɪk/', 'adjective', '{"zh-TW":["典範的；範例的"],"en":["serving as a typical example or pattern"]}', NULL, 'paradigmatic case / paradigmatic example / paradigmatic approach', '[{"en":"This experiment is a paradigmatic example of scientific rigor.","zh-TW":"這個實驗是科學嚴謹性的典範例子。"},{"en":"The paradigmatic approach guides how we frame the problem.","zh-TW":"典範方法指導我們如何框架問題。"}]', '{"noun":"paradigm","adverb":"paradigmatically"}', NULL, 4, 4789, NULL),
(4790, 'paradox', '/ˈpærədɒks/', 'noun', '{"zh-TW":["悖論；矛盾"],"en":["a seemingly absurd statement or position that may nonetheless be true"]}', NULL, 'logical paradox / apparent paradox / present a paradox', '[{"en":"The productivity paradox shows that more tools do not always mean better output.","zh-TW":"生產力悖論表明，更多工具並不總是意味著更好的產出。"},{"en":"It is a paradox that the safest roads have the most accidents.","zh-TW":"最安全的道路發生最多事故，這是一個悖論。"}]', '{"adjective":"paradoxical","adverb":"paradoxically"}', NULL, 3, 4790, NULL),
(4791, 'paradoxical', '/''pærəˌdɒksɪkəl/', 'adjective', '{"zh-TW":["矛盾的；悖論的"],"en":["seemingly absurd or contradictory, though possibly true"]}', NULL, 'paradoxical situation / paradoxical statement / paradoxical result', '[{"en":"It is paradoxical that the more choices people have, the less satisfied they feel.","zh-TW":"矛盾的是，人們擁有的選擇越多，他們感到越不滿意。"},{"en":"The paradoxical nature of the law meant that following it could still lead to penalties.","zh-TW":"這項法律的矛盾性質意味著遵守它仍然可能導致處罰。"}]', '{"adverb":"paradoxically","noun":"paradox"}', NULL, 4, 4791, NULL),
(4792, 'paradoxically', '/''pærəˈdɒksɪkəli/', 'adverb', '{"zh-TW":["矛盾地；自相矛盾地"],"en":["in a way that seems absurd or self-contradictory, although it may still be true"]}', NULL, 'paradoxically results / paradoxically more / paradoxically increase', '[{"en":"Paradoxically, the company grew fastest during the economic downturn.","zh-TW":"矛盾的是，公司在經濟低迷期間增長最快。"},{"en":"Paradoxically, simplifying the product line increased total revenue.","zh-TW":"矛盾的是，簡化產品線增加了總收入。"}]', '{"adjective":"paradoxical","noun":"paradox"}', NULL, 5, 4792, NULL),
(4793, 'parallel', '/ˈpærəlɛl/', 'adjective', '{"zh-TW":["平行的","類似的"],"en":["extending in the same direction","similar"]}', '{"root":{"text":"para","meaning":"beside (旁邊)"},"suffix":{"text":"llel","meaning":"each other"}}', 'parallel to / run parallel / draw a parallel', '[{"en":"The two roads run parallel to each other.","zh-TW":"兩條路平行延伸。"},{"en":"There are parallels between the two cases.","zh-TW":"兩個案例有相似之處。"}]', '{"noun":"parallel","adverb":"parallelly"}', NULL, 3, 4793, NULL),
(4794, 'parameter', '/pəˈræmɪtər/', 'noun', '{"zh-TW":["參數；範圍"],"en":["a limit or boundary; a variable"]}', '{"root":{"text":"para","meaning":"beside"},"suffix":{"text":"meter","meaning":"measure (量)"}}', 'within the parameters / set parameters', '[{"en":"We must work within the parameters of the budget.","zh-TW":"我們必須在預算範圍內工作。"},{"en":"The manager set clear parameters for the project.","zh-TW":"經理為項目設定了明確的參數。"}]', NULL, NULL, 3, 4794, NULL),
(4795, 'paramount', '/''pærəmaʊnt/', 'adjective', '{"zh-TW":["最重要的；至高無上的"],"en":["more important than anything else; supreme"]}', NULL, 'of paramount importance / paramount concern / paramount issue', '[{"en":"Safety is of paramount importance on all construction sites.","zh-TW":"安全在所有建築工地上都是最重要的。"},{"en":"Customer satisfaction is the paramount concern for any service-based business.","zh-TW":"顧客滿意度是任何服務型企業最重要的關切。"}]', NULL, NULL, 3, 4795, NULL),
(4796, 'paraphrase', '/''pærəfreɪz/', 'verb', '{"zh-TW":["改述；用自己的話解釋"],"en":["to express the meaning of something using different words, often in a simpler form"]}', NULL, 'paraphrase a text / paraphrase accurately / paraphrase without plagiarizing', '[{"en":"Can you paraphrase the main idea of the article in your own words?","zh-TW":"你能用自己的話改述這篇文章的主要觀點嗎？"},{"en":"Paraphrasing helps you check your understanding of difficult material.","zh-TW":"改述有助於你檢查對困難材料的理解。"}]', '{"noun":"paraphrase"}', NULL, 4, 4796, NULL),
(4797, 'parent', '/ˈpɛrənt/', 'noun', '{"zh-TW":["父母；母公司"],"en":["a mother or father","a company that owns another"]}', NULL, 'parent company / single parent', '[{"en":"The parent company is in Japan.","zh-TW":"母公司在日本。"},{"en":"Many employees are working parents.","zh-TW":"許多員工是在職父母。"}]', '{"noun":"parent","adjective":"parental","noun2":"parenthood"}', NULL, 2, 4797, NULL),
(4798, 'parent company', '/ˈpeərənt ˈkʌmpəni/', 'noun', '{"zh-TW":["母公司"],"en":["a company that owns or controls other companies called subsidiaries"]}', NULL, 'report to the parent company / parent company guarantee', '[{"en":"The subsidiary receives financial support from its parent company.","zh-TW":"子公司從母公司獲得財務支持。"},{"en":"The parent company consolidated all subsidiary accounts.","zh-TW":"母公司合併了所有子公司的帳目。"}]', NULL, NULL, 5, 4798, NULL),
(4799, 'parent company guarantee', '/ˈpeərənt ˈkʌmpəni ˌɡærənˈtiː/', 'noun', '{"zh-TW":["母公司擔保"],"en":["a guarantee from a parent company supporting obligations of a subsidiary"]}', NULL, 'require a parent company guarantee / issue a parent company guarantee', '[{"en":"The landlord required a parent company guarantee for the subsidiary''s lease.","zh-TW":"房東要求母公司為子公司的租約提供擔保。"},{"en":"A parent company guarantee reduces credit risk in large contracts.","zh-TW":"母公司擔保降低了大型合約中的信用風險。"}]', NULL, NULL, 5, 4799, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4800, 'parent guarantee', '/ˈpeərənt ˌɡærənˈtiː/', 'noun', '{"zh-TW":["母公司擔保"],"en":["a guarantee provided by a parent company for its subsidiary obligations"]}', NULL, 'require a parent guarantee / provide a parent guarantee', '[{"en":"The lender required a parent guarantee before extending credit.","zh-TW":"貸款方在提供信貸前要求了母公司擔保。"},{"en":"A parent guarantee adds security to a subsidiary contract.","zh-TW":"母公司擔保為子公司合約增加了安全保障。"}]', NULL, NULL, 5, 4800, NULL),
(4801, 'parental leave', '/pəˈrentəl liːv/', 'noun', '{"zh-TW":["育嬰假；親職假"],"en":["time off work granted to parents after a child''s birth or adoption"]}', NULL, 'shared parental leave / parental leave policy / take parental leave', '[{"en":"Both parents are entitled to parental leave under the new policy.","zh-TW":"根據新政策，雙方父母均有權休育嬰假。"},{"en":"More companies are offering extended parental leave as a benefit.","zh-TW":"越來越多的公司將延長育嬰假作為福利提供。"}]', NULL, NULL, 5, 4801, NULL),
(4802, 'pari passu', '/ˌpæri ˈpæsjuː/', 'phrase', '{"zh-TW":["同等地位；按比例"],"en":["on equal footing; ranking equally with other creditors"]}', NULL, 'pari passu clause / pari passu basis / rank pari passu', '[{"en":"The new bonds will rank pari passu with existing senior notes.","zh-TW":"新債券將與現有優先票據具有同等地位。"},{"en":"Creditors are paid on a pari passu basis in liquidation.","zh-TW":"在清算中，債權人按同等比例獲得清償。"}]', NULL, NULL, 4, 4802, NULL),
(4803, 'parity', '/ˈpærɪti/', 'noun', '{"zh-TW":["平價；同等"],"en":["the state of being equal in status, value, or level"]}', NULL, 'achieve parity / parity with competitors', '[{"en":"The new pay scale brought salaries to parity with industry peers.","zh-TW":"新薪酬制度使薪資與同行業持平。"},{"en":"Currency parity means two currencies have the same exchange value.","zh-TW":"貨幣平價意味著兩種貨幣具有相同的匯率價值。"}]', '{"adjective":"at parity","opposite":"disparity"}', NULL, 2, 4803, NULL),
(4804, 'park', '/pɑːrk/', 'noun', '{"zh-TW":["公園；停車"],"en":["a public area for recreation","to leave a vehicle"]}', NULL, 'car park / industrial park', '[{"en":"The factory is in the industrial park.","zh-TW":"工廠在工業園區內。"},{"en":"Where can I park my car?","zh-TW":"我可以在哪裡停車？"}]', '{"noun":"park","verb":"park","noun2":"parking"}', NULL, 1, 4804, NULL),
(4805, 'parole', '/pəˈroʊl/', 'noun', '{"zh-TW":["假釋"],"en":["early release from prison with conditions"]}', NULL, 'on parole / parole board', '[{"en":"He was released on parole.","zh-TW":"他被假釋出獄。"},{"en":"The parole board denied his request.","zh-TW":"假釋委員會拒絕了他的請求。"}]', NULL, NULL, 2, 4805, NULL),
(4806, 'parser', '/ˈpɑːrsər/', 'noun', '{"zh-TW":["解析器"],"en":["a program or component that interprets structured data"]}', NULL, 'HTML parser / XML parser / JSON parser', '[{"en":"The parser extracts structured data from raw HTML documents.","zh-TW":"解析器從原始HTML文件中提取結構化數據。"},{"en":"A syntax error in the input caused the parser to fail.","zh-TW":"輸入中的語法錯誤導致解析器失敗。"}]', '{"verb":"parse","noun2":"parsing"}', NULL, 2, 4806, NULL),
(4807, 'part', 'pɑːrt', 'noun', '{"zh-TW":["部分；零件","角色"],"en":["a piece of something larger","a role in something"]}', NULL, 'spare part/take part', '[{"en":"Each part of the plan is important.","zh-TW":"計畫的每個部分都很重要。"}]', '{"verb":"participate","adjective":"partial","adverb":"partially"}', NULL, 1, 4807, NULL),
(4808, 'partial ownership', '/ˈpɑːrʃəl ˈoʊnərʃɪp/', 'noun', '{"zh-TW":["部分所有權"],"en":["owning a percentage of something rather than the whole"]}', NULL, 'acquire partial ownership / sell partial ownership', '[{"en":"The investor acquired partial ownership through a minority stake.","zh-TW":"投資者通過少數股份獲得了部分所有權。"},{"en":"Partial ownership allows risk sharing between multiple investors.","zh-TW":"部分所有權允許多個投資者分擔風險。"}]', NULL, NULL, 5, 4808, NULL),
(4809, 'partial payment', '/ˈpɑːrʃəl ˈpeɪmənt/', 'noun', '{"zh-TW":["部分付款"],"en":["a payment that covers only a portion of the total amount due"]}', NULL, 'accept partial payment / make a partial payment', '[{"en":"The client made a partial payment of 50% upon signing the contract.","zh-TW":"客戶在簽署合約時支付了50%的部分款項。"},{"en":"Partial payment terms helped the startup manage its cash flow.","zh-TW":"部分付款條款幫助新創公司管理了現金流。"}]', NULL, NULL, 5, 4809, NULL),
(4810, 'participate', '/pɑːrˈtɪsɪpeɪt/', 'verb', '{"zh-TW":["參與","參加；參與"],"en":["to take part in an activity"]}', '{"root":{"text":"part","meaning":"part (部分)"},"suffix":{"text":"-icipate","meaning":"take (取得)"},"logic":"取得一份參與，即「參與」。"}', 'participate in / active participant; participate in / active participation', '[{"en":"Everyone is encouraged to participate in the discussion.","zh-TW":"鼓勵每個人參與討論。"},{"en":"Over 500 people participated in the survey.","zh-TW":"超過500人參與了調查。"},{"en":"All employees are encouraged to participate.","zh-TW":"鼓勵所有員工參與。"},{"en":"She participated in the training program.","zh-TW":"她參加了培訓計劃。"}]', '{"noun":"participation","noun2":"participant","adjective":"participatory"}', NULL, 4, 4810, 170),
(4811, 'participation', 'pɑːrˌtɪsɪˈpeɪʃən', 'noun', '{"zh-TW":["參與；參加","加入"],"en":["the act of taking part","involvement"]}', NULL, 'encourage participation/active participation', '[{"en":"Active participation is encouraged.","zh-TW":"鼓勵積極參與。"}]', '{"verb":"participate","adjective":"participating"}', NULL, 5, 4811, 602),
(4812, 'particular', '/pərˈtɪkjələr/', 'adjective', '{"zh-TW":["特定的","特別的"],"en":["specific","special; exceptional"]}', '{"root":{"text":"partic","meaning":"part (部分)"},"suffix":{"text":"-ular","meaning":"...的"}}', 'in particular / particular attention / nothing in particular', '[{"en":"Is there anything in particular you need?","zh-TW":"有什麼特別需要的嗎？"},{"en":"Pay particular attention to the deadline.","zh-TW":"請特別注意截止日期。"}]', '{"adverb":"particularly"}', NULL, 4, 4812, 900),
(4813, 'particularism', '/pɑːˈtɪkjʊlərɪzəm/', 'noun', '{"zh-TW":["特殊主義"],"en":["the theory or practice of focusing on particular cases rather than general principles"]}', NULL, 'moral particularism / cultural particularism / methodological particularism', '[{"en":"Moral particularism argues that context determines what is right.","zh-TW":"道德特殊主義認為情境決定什麼是對的。"},{"en":"Particularism emphasizes local knowledge over universal theories.","zh-TW":"特殊主義強調地方知識勝過普世理論。"}]', '{"adjective":"particularist","adverb":"particularistically"}', NULL, 5, 4813, NULL),
(4814, 'particulate matter', '/pɑːˈtɪkjʊlɪt ˈmætər/', 'noun', '{"zh-TW":["顆粒物；懸浮微粒"],"en":["tiny particles in the air that can harm human health"]}', NULL, 'fine particulate matter / particulate matter pollution / reduce particulate matter', '[{"en":"Particulate matter from vehicle exhaust causes respiratory disease.","zh-TW":"來自車輛廢氣的顆粒物導致呼吸道疾病。"},{"en":"Cities monitor particulate matter levels to protect public health.","zh-TW":"城市監測顆粒物水平以保護公共健康。"}]', NULL, NULL, 5, 4814, NULL),
(4815, 'partisanship', '/ˈpɑːrtɪzənʃɪp/', 'noun', '{"zh-TW":["黨派性；黨派偏見"],"en":["strong, often blind, adherence to a party or faction"]}', NULL, 'political partisanship / bipartisan vs. partisanship / reduce partisanship', '[{"en":"Excessive partisanship prevents legislators from passing necessary compromises.","zh-TW":"過度的黨派性阻止立法者達成必要的妥協。"},{"en":"Media partisanship erodes public trust in objective journalism.","zh-TW":"媒體的黨派偏見侵蝕了公眾對客觀新聞的信任。"}]', '{"adjective":"partisan","noun2":"partisan"}', NULL, 4, 4815, NULL),
(4816, 'partner', 'ˈpɑːrtnər', 'verb', '{"zh-TW":["合作；合夥","配對"],"en":["to work together with","to form a partnership"]}', NULL, 'partner with/partner on a project', '[{"en":"We partnered with a local supplier.","zh-TW":"我們與本地供應商合作。"}]', '{"noun":"partner, partnership","adjective":"partnered"}', NULL, 3, 4816, 410),
(4817, 'partnership', '/ˈpɑːrtnərʃɪp/', 'noun', '{"zh-TW":["合夥；夥伴關係"],"en":["a relationship between partners"]}', '{"root":{"text":"partner","meaning":"夥伴"},"suffix":{"text":"-ship","meaning":"狀態"}}', 'form a partnership / business partnership / in partnership with', '[{"en":"The two companies formed a strategic partnership.","zh-TW":"兩家公司建立了策略夥伴關係。"},{"en":"We work in partnership with local suppliers.","zh-TW":"我們與當地供應商合作。"}]', '{"noun":"partner"}', NULL, 4, 4817, NULL),
(4818, 'partnership agreement', '/ˈpɑːrtnərʃɪp əˈɡriːmənt/', 'noun', '{"zh-TW":["合夥協議"],"en":["a legal document defining the rights, duties, and profit share of partners"]}', NULL, 'sign a partnership agreement / partnership agreement terms', '[{"en":"The partnership agreement specified each partner''s capital contribution.","zh-TW":"合夥協議規定了每位合夥人的資本出資。"},{"en":"Disputes between partners are governed by the partnership agreement.","zh-TW":"合夥人之間的糾紛由合夥協議管轄。"}]', NULL, NULL, 5, 4818, NULL),
(4819, 'party', '/ˈpɑːrti/', 'noun', '{"zh-TW":["【主要意義-名詞】派對；聚會；政黨","【次要意義-名詞（法律）】當事人；一方（合約或訴訟中）","【次要意義-動詞】參與；加入"],"en":["[primary - noun] a social gathering; a political organization","[secondary - noun] a person or group involved in a legal agreement or dispute","[secondary - verb] to attend or take part in parties or celebrations"]}', NULL, 'third party / the contracting parties / party to an agreement / party involved', '[{"en":"Both parties must sign the agreement before it takes effect.","zh-TW":"雙方必須在協議生效之前簽署。"},{"en":"A third-party inspection is required before the goods are shipped.","zh-TW":"貨物出貨前需要第三方檢驗。"},{"en":"Please ensure all parties involved are notified of the schedule change.","zh-TW":"請確保所有相關方都被通知到時間表的變更。"}]', '{"adjective":"bipartisan"}', 'party 在法律和商業語境中意為「當事人/一方」，third party（第三方）、contracting parties（締約方）是 TOEIC 合約類文章必考詞彙，考生常誤以為只有「派對」的意思。', 2, 4819, NULL),
(4820, 'pass', '/pæs/', 'verb', '{"zh-TW":["通過；傳遞"],"en":["to go by","to hand over"]}', NULL, 'pass a test / pass along', '[{"en":"She passed the certification exam.","zh-TW":"她通過了認證考試。"},{"en":"Please pass this information along.","zh-TW":"請將這個消息轉達。"}]', '{"verb":"pass","noun":"pass","noun2":"passage","noun3":"passenger"}', NULL, 1, 4820, NULL),
(4821, 'pass mark', '/pɑːs mɑːrk/', 'noun', '{"zh-TW":["及格分數"],"en":["the minimum score needed to pass an exam or course"]}', NULL, 'achieve the pass mark / below the pass mark', '[{"en":"The pass mark for the exam is 60%.","zh-TW":"這門考試的及格分數是60%。"},{"en":"She exceeded the pass mark by 20 points.","zh-TW":"她超過及格分數20分。"}]', NULL, NULL, 3, 4821, NULL),
(4822, 'passing off', '/ˌpɑːsɪŋ ˈɒf/', 'noun', '{"zh-TW":["仿冒；商品混同"],"en":["misrepresenting goods or services as those of another established brand"]}', NULL, 'sue for passing off / passing off claim', '[{"en":"The company successfully sued a competitor for passing off its products.","zh-TW":"公司成功地起訴了一家以仿冒其產品的競爭對手。"},{"en":"Passing off can lead to significant legal damages and injunctions.","zh-TW":"商品混同可能導致重大法律損害賠償和禁令。"}]', NULL, NULL, 4, 4822, NULL),
(4823, 'passionate', '/ˈpæʃənət/', 'adjective', '{"zh-TW":["熱情的；熱烈的"],"en":["showing or caused by strong feelings"]}', '{"root":{"text":"passion","meaning":"suffer/feel (承受/感受)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"具有強烈感受的，即「熱情的」。"}', 'passionate about / passionate speech', '[{"en":"He is passionate about environmental protection.","zh-TW":"他對環境保護充滿熱情。"},{"en":"She gave a passionate speech about equality.","zh-TW":"她發表了一場關於平等的激昂演說。"}]', '{"noun":"passion","adverb":"passionately"}', NULL, 4, 4823, NULL),
(4824, 'passport', '/ˈpæspɔːrt/', 'noun', '{"zh-TW":["護照"],"en":["an official document for international travel"]}', NULL, 'valid passport / passport control', '[{"en":"Your passport must be valid for six months.","zh-TW":"您的護照必須有六個月有效期。"},{"en":"Please present your passport at the immigration desk.","zh-TW":"請在入境檢查台出示護照。"}]', NULL, NULL, 3, 4824, NULL),
(4825, 'passport control', '/''pɑːspɔːrt kənˌtrəʊl/', 'noun', '{"zh-TW":["護照查驗；出入境管制"],"en":["the area at an airport or border where officials check travelers'' passports"]}', NULL, 'pass through passport control / passport control queue / after passport control', '[{"en":"The queue at passport control took over an hour during peak travel time.","zh-TW":"在旅遊旺季，護照查驗的隊伍需要超過一個小時。"},{"en":"After passing through passport control, she collected her luggage.","zh-TW":"通過護照查驗後，她取回了行李。"}]', NULL, NULL, 5, 4825, NULL),
(4826, 'password', '/ˈpɑːswɜːrd/', 'noun', '{"zh-TW":["密碼"],"en":["a secret word used to gain access to a system"]}', NULL, 'strong password / reset a password', '[{"en":"Use a strong password with a mix of letters and numbers.","zh-TW":"使用包含字母和數字組合的強密碼。"},{"en":"Please reset your password every 90 days.","zh-TW":"請每90天重設密碼。"}]', NULL, NULL, 3, 4826, NULL),
(4827, 'past', '/pæst/', 'noun', '{"zh-TW":["過去"],"en":["the time before now"]}', NULL, 'in the past / past experience', '[{"en":"In the past, we used a different system.","zh-TW":"過去我們使用不同的系統。"},{"en":"Her past experience is very relevant.","zh-TW":"她過去的經驗非常相關。"}]', '{"noun":"past","adjective":"past","preposition":"past"}', NULL, 1, 4827, NULL),
(4828, 'pasteurize', '/''pæstʃəraɪz/', 'verb', '{"zh-TW":["巴氏殺菌；低溫消毒"],"en":["to heat food or drink to a specific temperature to kill harmful bacteria"]}', NULL, 'pasteurize milk / pasteurize juice / required to pasteurize', '[{"en":"All commercial milk products must be pasteurized before they are sold.","zh-TW":"所有商業牛奶產品在銷售前必須進行巴氏殺菌。"},{"en":"The pasteurization process extends the shelf life of dairy products significantly.","zh-TW":"巴氏殺菌過程顯著延長了乳製品的保質期。"}]', '{"noun":"pasteurization","adjective":"pasteurized"}', NULL, 4, 4828, NULL),
(4829, 'pastiche', '/pæˈstiːʃ/', 'noun', '{"zh-TW":["仿作；拼貼（文藝）"],"en":["a work imitating the style of another artist or period"]}', NULL, 'clever pastiche / literary pastiche / playful pastiche', '[{"en":"The film is a loving pastiche of 1960s spy thrillers.","zh-TW":"這部電影是對1960年代間諜驚悚片的深情仿作。"},{"en":"His novel is a postmodern pastiche mixing various literary styles.","zh-TW":"他的小說是一部混合各種文學風格的後現代仿作。"}]', NULL, NULL, 3, 4829, NULL),
(4830, 'pastry', '/ˈpeɪstri/', 'noun', '{"zh-TW":["糕點；西點"],"en":["a baked food made from dough containing fat"]}', NULL, 'fresh pastry / pastry selection', '[{"en":"The bakery offers a wide selection of pastries.","zh-TW":"麵包店提供各式各樣的糕點。"},{"en":"We ordered coffee and a pastry for breakfast.","zh-TW":"我們點了咖啡和糕點作為早餐。"}]', NULL, NULL, 2, 4830, NULL),
(4831, 'patch', '/pætʃ/', 'noun', '{"zh-TW":["修補程式；補丁"],"en":["a software update that fixes bugs or security vulnerabilities"]}', NULL, 'security patch / software patch / apply a patch / patch management', '[{"en":"Install the security patch immediately to prevent exploitation.","zh-TW":"立即安裝安全修補程式以防止漏洞被利用。"},{"en":"Patch management ensures all systems are up to date.","zh-TW":"修補程式管理確保所有系統保持最新狀態。"}]', '{"verb":"patch","adjective":"patched"}', NULL, 2, 4831, NULL),
(4832, 'patent', '/ˈpætənt/', 'noun', '{"zh-TW":["專利"],"en":["an official right to be the only maker of an invention","an official right to an invention"]}', '{"root":{"text":"pat","meaning":"open (公開)"}}', 'file a patent / patent pending; file a patent / patent application / patent holder', '[{"en":"She filed a patent for her invention.","zh-TW":"她為她的發明申請了專利。"},{"en":"The patent expires next year.","zh-TW":"專利明年到期。"},{"en":"The company filed a patent for the new design.","zh-TW":"公司為新設計申請了專利。"}]', '{"verb":"patent","adjective":"patented"}', NULL, 2, 4832, NULL),
(4833, 'patent application', '/ˈpeɪtənt ˌæplɪˈkeɪʃən/', 'noun', '{"zh-TW":["專利申請"],"en":["a formal request submitted to a patent office for intellectual property protection"]}', NULL, 'file a patent application / patent application approval', '[{"en":"The company filed a patent application for its new manufacturing process.","zh-TW":"公司為其新製造工藝提交了專利申請。"},{"en":"A successful patent application blocks competitors from copying the invention.","zh-TW":"成功的專利申請阻止競爭者複製該發明。"}]', NULL, NULL, 5, 4833, NULL),
(4834, 'patent infringement', '/ˈpeɪtənt ɪnˈfrɪndʒmənt/', 'noun', '{"zh-TW":["專利侵犯"],"en":["the unauthorized use of a patented invention without the owner''s permission"]}', NULL, 'commit patent infringement / sue for patent infringement', '[{"en":"The company sued a competitor for patent infringement of its key technology.","zh-TW":"公司起訴一家競爭對手侵犯其關鍵技術的專利。"},{"en":"Patent infringement claims can result in injunctions and financial damages.","zh-TW":"專利侵犯索賠可能導致禁令和財務損害賠償。"}]', '{"noun":"infringer","verb":"infringe"}', NULL, 5, 4834, NULL),
(4835, 'patent protection', '/ˈpeɪtənt prəˈtekʃən/', 'noun', '{"zh-TW":["專利保護"],"en":["legal protection granted to inventors giving exclusive rights to their inventions"]}', NULL, 'seek patent protection / patent protection period', '[{"en":"Patent protection lasts 20 years from the date of filing.","zh-TW":"專利保護從申請日起持續20年。"},{"en":"Strong patent protection discourages competitors from copying innovations.","zh-TW":"強有力的專利保護阻止競爭者抄襲創新。"}]', NULL, NULL, 5, 4835, NULL),
(4836, 'path', '/pæθ/', 'noun', '{"zh-TW":["道路；途徑"],"en":["a way or track","a course of action"]}', NULL, 'career path / on the right path', '[{"en":"What is your career path?","zh-TW":"你的職涯路徑是什麼？"},{"en":"We are on the right path to success.","zh-TW":"我們在通往成功的正確路上。"}]', '{"noun":"path","noun2":"pathway"}', NULL, 1, 4836, NULL),
(4837, 'path dependency', '/pɑːθ dɪˈpendənsi/', 'noun', '{"zh-TW":["路徑依賴"],"en":["the tendency for prior decisions to constrain future choices"]}', NULL, 'path dependency in institutions / strong path dependency / overcome path dependency', '[{"en":"Path dependency explains why countries develop different welfare systems.","zh-TW":"路徑依賴解釋了為什麼各國發展出不同的福利制度。"},{"en":"Technological path dependency makes it hard to switch from established platforms.","zh-TW":"技術路徑依賴使得從已建立的平台轉換變得困難。"}]', NULL, NULL, 5, 4837, NULL),
(4838, 'path-breaking', '/pɑːθ ˈbreɪkɪŋ/', 'adjective', '{"zh-TW":["開創性的；突破性的"],"en":["pioneering; creating a new path for others to follow"]}', NULL, 'path-breaking research / path-breaking innovation / path-breaking work', '[{"en":"Her path-breaking research opened a new field of study.","zh-TW":"她開創性的研究開創了一個新的研究領域。"},{"en":"The company''s path-breaking product design was widely imitated by competitors.","zh-TW":"公司開創性的產品設計被競爭對手廣泛模仿。"}]', NULL, NULL, 5, 4838, NULL),
(4839, 'pathogen', '/ˈpæθədʒən/', 'noun', '{"zh-TW":["病原體"],"en":["an organism causing disease, such as a bacterium, virus, or fungus"]}', NULL, 'identify the pathogen / pathogen detection / drug-resistant pathogen', '[{"en":"The pathogen was identified as a drug-resistant strain of bacteria.","zh-TW":"病原體被確認為耐藥細菌菌株。"},{"en":"Understanding how pathogens spread is crucial for public health.","zh-TW":"理解病原體如何傳播對公共衛生至關重要。"}]', '{"adjective":"pathogenic","noun":"pathogenicity"}', NULL, 3, 4839, NULL),
(4840, 'pathology', '/pəˈθɒlədʒi/', 'noun', '{"zh-TW":["病理學"],"en":["the study of the causes and effects of diseases"]}', NULL, 'clinical pathology / pathology report / pathology department', '[{"en":"The pathology report confirmed the diagnosis of lymphoma.","zh-TW":"病理報告確認了淋巴瘤的診斷。"},{"en":"Advances in molecular pathology have improved diagnostic accuracy.","zh-TW":"分子病理學的進步提高了診斷準確性。"}]', '{"adjective":"pathological","adverb":"pathologically"}', NULL, 3, 4840, NULL),
(4841, 'patient', '/ˈpeɪʃənt/', 'adjective', '{"zh-TW":["有耐心的；病人","有耐心的"],"en":["able to wait calmly","a person receiving medical care","able to wait without becoming annoyed"]}', '{"root":{"text":"pati","meaning":"suffer/endure (承受)"},"suffix":{"text":"-ent","meaning":"being (…的)"},"logic":"能承受等待的，即「有耐心的」。"}', 'be patient / patient care; be patient / patient with', '[{"en":"Please be patient; we are working on it.","zh-TW":"請有耐心，我們正在處理中。"},{"en":"Patient satisfaction is our priority.","zh-TW":"病患滿意度是我們的首要任務。"},{"en":"Please be patient while we process your request.","zh-TW":"請耐心等候我們處理您的要求。"},{"en":"Good teachers are patient with students.","zh-TW":"好老師對學生有耐心。"}]', '{"adjective":"patient","noun":"patient","noun2":"patience","adjective2":"impatient","adverb":"patiently"}', NULL, 3, 4841, NULL),
(4842, 'patron', '/ˈpeɪtrən/', 'noun', '{"zh-TW":["顧客；贊助人"],"en":["a customer; a supporter"]}', '{"root":{"text":"patr","meaning":"father (父親)"}}', 'regular patron / patron of the arts', '[{"en":"The restaurant values its regular patrons.","zh-TW":"餐廳重視常客。"},{"en":"She is a well-known patron of the arts.","zh-TW":"她是知名的藝術贊助人。"}]', '{"noun":"patronage","verb":"patronize"}', NULL, 2, 4842, NULL),
(4843, 'patronage', '/ˈpætrənɪdʒ/', 'noun', '{"zh-TW":["惠顧；贊助"],"en":["regular custom to a business; support"]}', '{"root":{"text":"patr","meaning":"father (父親)"},"suffix":{"text":"-age","meaning":"行為"}}', 'thank you for your patronage / patronage of the arts', '[{"en":"Thank you for your continued patronage.","zh-TW":"感謝您持續的惠顧。"},{"en":"The museum relies on corporate patronage.","zh-TW":"博物館依靠企業贊助。"}]', '{"noun":"patron","verb":"patronize"}', NULL, 3, 4843, NULL),
(4844, 'patronize', '/ˈpeɪtrənaɪz/', 'verb', '{"zh-TW":["光顧；資助；以高人一等的態度對待"],"en":["to be a regular customer; to condescend toward someone"]}', NULL, 'patronize a business / patronize local stores / patronize someone', '[{"en":"Customers were encouraged to patronize local businesses to support the community.","zh-TW":"鼓勵顧客光顧當地企業以支持社區。"},{"en":"His tone was patronizing, which alienated his junior colleagues.","zh-TW":"他的語氣盛氣凌人，疏遠了他的下屬同事。"}]', '{"noun":"patronage","adjective":"patronizing","adverb":"patronizingly"}', NULL, 3, 4844, NULL),
(4845, 'pattern', '/ˈpætərn/', 'noun', '{"zh-TW":["模式；圖案"],"en":["a regular form or order"]}', NULL, 'behavior pattern / follow a pattern / pattern of growth', '[{"en":"We noticed a pattern in customer complaints.","zh-TW":"我們注意到客訴的模式。"},{"en":"Sales follow a seasonal pattern.","zh-TW":"銷售遵循季節性模式。"}]', '{"adjective":"patterned"}', NULL, 3, 4845, NULL),
(4846, 'pause', '/pɔːz/', 'verb', '{"zh-TW":["暫停"],"en":["to stop briefly"]}', NULL, 'pause for a moment / without pause', '[{"en":"Let''s pause the meeting for a short break.","zh-TW":"讓我們暫停會議休息一下。"},{"en":"He paused before answering the question.","zh-TW":"他回答前停頓了一下。"}]', '{"noun":"pause"}', NULL, 2, 4846, NULL),
(4847, 'pay', '/peɪ/', 'verb', '{"zh-TW":["支付；薪資"],"en":["to give money for something","money received for work"]}', NULL, 'pay raise / pay off', '[{"en":"The investment will pay off in the long run.","zh-TW":"這項投資從長遠來看會有回報。"},{"en":"She asked for a pay raise.","zh-TW":"她要求加薪。"}]', '{"verb":"pay","noun":"pay","noun2":"payment","noun3":"payroll","adjective":"payable"}', NULL, 1, 4847, NULL),
(4848, 'pay equity', '/peɪ ˈekwɪti/', 'noun', '{"zh-TW":["薪酬公平"],"en":["ensuring employees are paid equally for equal or equivalent work"]}', NULL, 'achieve pay equity / pay equity audit / gender pay equity', '[{"en":"The company conducted a pay equity audit to close wage gaps.","zh-TW":"公司進行了薪酬公平審計以縮小薪資差距。"},{"en":"Pay equity initiatives are increasingly required by law.","zh-TW":"薪酬公平倡議越來越多地被法律所要求。"}]', NULL, NULL, 4, 4848, NULL),
